// Writes a library of the old MetaboliteDetector 3.3 (Linux) as AMDIS MSL in the three export types of
// `LibrarySearch::exportMSL`, without its GUI. See make-msl-export.sh for how it is used.
//
// Loaded with LD_PRELOAD into the old binary: it replaces main() and calls the binary's own
// LibrarySearch::fromDisk and exportMSL by address (addresses come from syms.inc, generated by nm).
#include <dlfcn.h>
#include <cstdint>
#include <cstdio>
#include <exception>
#include <string>

namespace {

uintptr_t base;

template <class F> F fn(uintptr_t addr) { return reinterpret_cast<F>(base + addr); }

#define SYM(name, addr) constexpr uintptr_t name = addr;
#include "syms.inc"
#undef SYM

// usage: LD_PRELOAD=old_msl_export.so metabolitedetector_app LIB.lbr|LIB.msl OUT_PREFIX
// writes OUT_PREFIX.profile.msl, OUT_PREFIX.nominal.msl and OUT_PREFIX.fwhm.msl (ExportType 0, 1, 2).
int export_main(int argc, char** argv, char**) {
    if (argc < 3) {
        std::fprintf(stderr, "usage: %s LIB.lbr|LIB.msl OUT_PREFIX\n", argv[0]);
        return 2;
    }
    // fromDisk and importMSL are static and return a new LibrarySearch.
    const std::string input = argv[1];
    const bool msl = input.size() > 4 && input.compare(input.size() - 4, 4, ".msl") == 0;
    const void* lib = nullptr;
    try {
        lib = fn<const void* (*)(const char*)>(msl ? LIBRARY_SEARCH_IMPORT_MSL : LIBRARY_SEARCH_FROM_DISK)(argv[1]);
    } catch (const std::exception& e) {
        std::fprintf(stderr, "fromDisk: %s\n", e.what());
        return 1;
    } catch (...) {
        std::fprintf(stderr, "fromDisk failed\n");
        return 1;
    }
    if (!lib) return 1;
    const char* names[] = {"profile", "nominal", "fwhm"};
    for (int t = 0; t < 3; t++) {
        std::string path = std::string(argv[2]) + "." + names[t] + ".msl";
        try {
            fn<void (*)(const void*, const char*, int)>(LIBRARY_SEARCH_EXPORT_MSL)(lib, path.c_str(), t);
        } catch (const std::exception& e) {
            std::fprintf(stderr, "exportMSL %d: %s\n", t, e.what());
        } catch (...) {
            std::fprintf(stderr, "exportMSL %d failed\n", t);
        }
    }
    return 0;
}

}  // namespace

extern "C" int __libc_start_main(int (*main)(int, char**, char**), int argc, char** argv, void (*init)(),
                                 void (*fini)(), void (*rtld_fini)(), void* stack_end) {
    base = reinterpret_cast<uintptr_t>(main) - MAIN;
    using Start = int (*)(int (*)(int, char**, char**), int, char**, void (*)(), void (*)(), void (*)(), void*);
    auto real = reinterpret_cast<Start>(dlsym(RTLD_NEXT, "__libc_start_main"));
    return real(export_main, argc, argv, init, fini, rtld_fini, stack_end);
}
